const D = { density: .55, energy: .6, scale: 1, speed: 1, spread: .5, hue: 0, x: .5, y: .5, style: 'wildfire', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- grid dims (scale -> cell size; larger scale = chunkier cells / coarser grid) ----
const CW = Math.max(56, Math.min(184, Math.round(152 / Math.max(0.4, P.scale))));
const CH = Math.max(40, Math.min(184, Math.round(CW * height / Math.max(1, width))));
const NC = CW * CH;
const seedI = P.seed | 0;

// deterministic uniform hash (no p5 random); Math.imul keeps the 32-bit mix exact
const gh = (i, s) => { let h = (i * 374761393 + s * 668265263 + seedI * 2654435761) | 0; h = Math.imul(h ^ (h >>> 13), 1274126177); h ^= h >>> 16; return (h >>> 0) / 4294967296; };

// ---- (re)build the forest on size / seed change ----
const buildSig = CW + 'x' + CH + '_' + seedI;
if (S.buildSig !== buildSig || !S.state) {
  S.buildSig = buildSig;
  S.state = new Uint8Array(NC);   // 0 empty/soil, 1 tree, 2 burning
  S.next = new Uint8Array(NC);
  S.heat = new Uint8Array(NC);    // ember/fire glow, decays
  S.tex = new Uint8Array(NC);     // stable canopy/soil texture
  const st = S.state, tx = S.tex;
  for (let k = 0; k < NC; k++) { st[k] = gh(k, 7) < 0.58 ? 1 : 0; tx[k] = (gh(k, 4242) * 255) | 0; }
  // a handful of initial fire seeds so the very first frame already has fronts
  for (let a = 0; a < 5; a++) { const c = (gh(a + 1, 91) * NC) | 0; if (st[c] === 1) { st[c] = 2; S.heat[c] = 255; } }
  S.step = null;
}

// ---- section-driven dramaturgy: fire seasons (dry burn / wet regrow), palette drift ----
const secPhase = K.section * 0.9 + K.t * 0.021;
const season = 0.5 + 0.5 * Math.sin(secPhase);                 // 0 wet .. 1 dry
const hueOff = P.hue + K.section * 9 + K.t * 1.2;
const growthP = 0.010 + P.density * 0.045 + (1 - season) * 0.028;
let strikes = Math.max(1, Math.round(0.3 + P.density * 1.3 + season * 1.7 + K.intensity * 1.1 + A.bass * 4));
const spreadPow = 0.55 + P.spread * 0.42;                       // fire-catch probability
const sx = (P.x * CW) | 0, sy = (P.y * CH) | 0;                 // storm-center bias for strikes
const stormR = Math.round((0.16 + (1 - P.spread) * 0.34) * Math.min(CW, CH));

// ---- clock -> generations/sec (continuous K.t drives evolution; never re-phases) ----
const gps = 2.5 + P.speed * 5 + K.intensity * 2.5;
const target = Math.floor(K.t * gps);

// ---- one synchronous CA generation ----
function evolve(gen) {
  const st = S.state, nx = S.next, ht = S.heat;
  for (let j = 0; j < CH; j++) {
    const jm = (j - 1 + CH) % CH, jp = (j + 1) % CH, rj = j * CW, rjm = jm * CW, rjp = jp * CW;
    for (let i = 0; i < CW; i++) {
      const idx = rj + i, s = st[idx];
      if (s === 2) { nx[idx] = 0; }                               // burning -> ash
      else if (s === 1) {                                         // tree: catch from any burning Moore neighbor
        const im = (i - 1 + CW) % CW, ip = (i + 1) % CW;
        let burn = 0;
        if (st[rjm + im] === 2 || st[rjm + i] === 2 || st[rjm + ip] === 2 ||
            st[rj + im] === 2 || st[rj + ip] === 2 ||
            st[rjp + im] === 2 || st[rjp + i] === 2 || st[rjp + ip] === 2) burn = 1;
        nx[idx] = (burn && gh(idx, gen * 5 + 1) < spreadPow) ? 2 : 1;
      } else {                                                    // ash/soil -> regrow tree
        nx[idx] = gh(idx, gen) < growthP ? 1 : 0;
      }
    }
  }
  // lightning strikes near the storm center ignite trees
  for (let a = 0; a < strikes; a++) {
    const ang = gh(a * 3 + 1, gen * 7 + 2) * 6.283, rr = gh(a * 3 + 2, gen * 7 + 5);
    const ci = ((sx + Math.round(Math.cos(ang) * rr * stormR)) % CW + CW) % CW;
    const cj = ((sy + Math.round(Math.sin(ang) * rr * stormR)) % CH + CH) % CH;
    const ci2 = ci * 1, cidx = cj * CW + ci2;
    if (nx[cidx] === 1) nx[cidx] = 2;
  }
  // heat: spike on burning, exponential ember decay elsewhere
  for (let k = 0; k < NC; k++) { if (nx[k] === 2) ht[k] = 255; else { const hv = ht[k]; ht[k] = hv > 4 ? (hv * 176) >> 8 : 0; } }
  const tmp = S.state; S.state = S.next; S.next = tmp;
}

// ---- advance generations (guard t0 resets, cap catch-up so a time-jump can't torch everything) ----
if (S.step == null || target < S.step) S.step = target;
if (target - S.step > 8) { S.step = target; }
else { let guard = 0; while (S.step < target && guard < 4) { evolve(S.step); S.step++; guard++; } }

// ---- coarse buffer ----
if (!S.g || S.gw !== CW || S.gh !== CH) { S.g = createGraphics(CW, CH); S.g.pixelDensity(1); S.gw = CW; S.gh = CH; }

// ---- HSV -> rgb 0..255 (no per-pixel alloc), exposure + global hue offset baked in ----
const OUT = [0, 0, 0];
const eexp = Math.min(1.45, 0.55 + P.energy * 0.85 + K.intensity * 0.2 + A.rms * 0.4);
function put(h, s, v) {
  h = ((h + hueOff) % 360 + 360) % 360; v = Math.min(1, v * eexp); s = s < 0 ? 0 : (s > 1 ? 1 : s);
  const c = v * s, x = c * (1 - Math.abs((h / 60) % 2 - 1)), m = v - c;
  let r, g, b;
  if (h < 60) { r = c; g = x; b = 0; } else if (h < 120) { r = x; g = c; b = 0; } else if (h < 180) { r = 0; g = c; b = x; }
  else if (h < 240) { r = 0; g = x; b = c; } else if (h < 300) { r = x; g = 0; b = c; } else { r = c; g = 0; b = x; }
  OUT[0] = (r + m) * 255; OUT[1] = (g + m) * 255; OUT[2] = (b + m) * 255;
}
function fire(hn) { put(6 + hn * 50, 1.15 - hn * 0.6, 0.1 + hn * 1.05); }
function thermal(v) { v = v < 0 ? 0 : (v > 1 ? 1 : v); put(250 - v * 250, v > 0.85 ? 0.9 - (v - 0.85) * 5 : 0.9, 0.24 + v * 0.72); }

const style = P.style;
let col;
if (style === 'ember-night') {
  col = (s, hn, tv) => { if (s === 2) fire(hn); else if (s === 1) put(126 + tv * 34, 0.85, 0.09 + tv * 0.06); else if (hn > 0.05) fire(hn); else put(18, 0.7, 0.018 + hn); };
} else if (style === 'autumn') {
  col = (s, hn, tv) => { if (s === 2) put(4 + hn * 34, 1.1 - hn * 0.45, 0.14 + hn * 0.92); else if (s === 1) put(24 + tv * 26, 0.82, 0.3 + tv * 0.2); else if (hn > 0.07) put(8 + hn * 26, 0.88, hn * 0.86 + 0.05); else put(20, 0.5, 0.09 + tv * 0.03); };
} else if (style === 'toxic') {
  col = (s, hn, tv) => { if (s === 2) put(150 + hn * 44, 1 - hn * 0.5, 0.16 + hn * 0.9); else if (s === 1) put(154 + tv * 42, 0.72, 0.26 + tv * 0.18); else if (hn > 0.07) put(168 + hn * 30, 0.82, hn * 0.82 + 0.05); else put(284, 0.5, 0.085 + tv * 0.03); };
} else if (style === 'heatmap') {
  col = (s, hn, tv) => { if (s === 2) thermal(1); else if (s === 0) thermal(hn * 0.82); else thermal(0.30 + tv * 0.08); };
} else { // wildfire (default)
  col = (s, hn, tv) => { if (s === 2) fire(hn); else if (s === 1) put(92 + tv * 44, 0.55 + tv * 0.25, 0.34 + tv * 0.2); else if (hn > 0.06) fire(hn); else put(24, 0.45, 0.1 + tv * 0.03); };
}

// ---- render buffer (rebuild on generation / live-poke change) ----
const rsig = S.step + '|' + style + '|' + Math.round(hueOff) + '|' + Math.round(eexp * 20) + '|' + CW + 'x' + CH;
if (S.rsig !== rsig) {
  S.rsig = rsig;
  const g = S.g; g.loadPixels(); const px = g.pixels, st = S.state, ht = S.heat, tx = S.tex;
  for (let k = 0; k < NC; k++) {
    col(st[k], ht[k] / 255, tx[k] / 255);
    const o = 4 * k; px[o] = OUT[0]; px[o + 1] = OUT[1]; px[o + 2] = OUT[2]; px[o + 3] = 255;
  }
  g.updatePixels();
}

// ---- draw: upscale with bounded zoom-breath + micro-rotation (motion floor insurance, no black edges) ----
const ang = Math.sin(K.t * 0.05) * 0.05;
const zoom = 1.14 + Math.sin(K.t * 0.09) * 0.03 + A.rms * 0.1;
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
translate(width / 2, height / 2);
rotate(ang);
scale(zoom);
imageMode(CENTER);
image(S.g, 0, 0, width, height);
pop();
imageMode(CORNER);

// ---- audio warmth ON TOP of the clk baseline (all-zero during validation; partial alpha, never strobes) ----
if (A.bass > 0.01 || A.treble > 0.01 || A.rms > 0.01) {
  push(); blendMode(ADD); noStroke();
  fill((hueOff + 24) % 360, 55, 100, (A.bass * 0.55 + A.rms * 0.35) * P.energy * 16);
  rect(0, 0, width, height);
  fill((hueOff + 50) % 360, 25, 100, A.treble * P.energy * 11);
  rect(0, 0, width, height);
  blendMode(BLEND); pop();
}
